mapper.select:
select w.wo_no, i.item_cd, i.item_nm, trim_scale(w.plan_qty)::text as plan_qty, w.unit_cd, w.status, w.plan_end, w.plan_start
  from prd_wo w
  join mst_item i on i.item_id = w.item_id
 where w.status in ('RELEASED', 'IN_PROGRESS')
   and w.plan_start <= #{today}
   and w.plant_cd = #{plantCd}
 order by w.priority, w.plan_start, w.wo_id
 limit #{limit}
